import{_ as s,a0 as a,w as r,s as d,ao as l,I as p,x as t,a1 as o,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"如何在Linux中发现IP地址冲突 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux中发现IP地址冲突 | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux中发现IP地址冲突 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux中发现IP地址冲突 | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/How To Find IP Conflicts In Linux","title":"如何在Linux中发现IP地址冲突","tag":"201404","desc":""},"relativePath":"201404/How To Find IP Conflicts In Linux.md","filePath":"[post].md"}'),u={name:"201404/How To Find IP Conflicts In Linux.md"};function I(P,n,x,T,f,m){const e=a("Link");return r(),d("div",null,[n[11]||(n[11]=l(`<h1 id="如何在linux中发现ip地址冲突" tabindex="-1">如何在Linux中发现IP地址冲突 <a class="header-anchor" href="#如何在linux中发现ip地址冲突" aria-label="Permalink to “如何在Linux中发现IP地址冲突”">​</a></h1><p>你们都知道什么是IP地址，是吧？它们被分配给网络上的设备来代表它们。它们通过DHCP服务器分配并且会经常改变。现在有两种IP地址。动态的一种会经常改变（几天一次），而静态的就如它的名字那样是静态的，意味着它们不会改变。</p><p>有时这会引发一些冲突。当一个动态IP被分配了并且有另外一台网络设备已经拥有了相同的IP。或者在相同网络子网上有多台分配IP的DHCP服务器。如果你有连通问题并且假设它是由于IP冲突造成的，那么你可以使用一个工具称作arp-scan来扫描它们。</p><p>这个工具会在本地网络发送ARP（Address Resolution Protocol）(地址解析协议)包来收集地址。如果有多个MAC地址声称拥有相同的IP地址，那么这里就存在冲突。</p><p>要在Ubuntu或者Debian上安装arp-scan则输入：</p><pre><code>$ sudo apt-get install arp-scan
</code></pre><p>对于Fedora，CentOS或者RedHat：</p><pre><code>$ sudo yum install arp-scan
</code></pre><p>要检测IP冲突，运行下面的命令:</p><pre><code>$ sudo arp-scan –I eth0 -l
</code></pre><p>输出示例：</p><pre><code>192.168.1.10   00:1b:a9:63:a2:4c       BROTHER INDUSTRIES, LTD.
192.168.1.30   00:1e:8f:58:ec:49       CANON INC.
192.168.1.33   00:25:4b:1b:10:20       Apple, Inc
192.168.1.37   10:9a:dd:55:d7:95       Apple Inc
192.168.1.38   20:c9:d0:27:8d:56       (Unknown)
192.168.1.39   d4:85:64:4d:35:be       Hewlett Packard
192.168.1.39   00:0b:46:e4:8e:6d       Cisco (DUP: 2)
192.168.1.40   90:2b:34:18:59:c0       (Unknown)
</code></pre><p>在本例中，<strong>192.168.1.39</strong>这个IP冲突了，因为它出现了两次。</p><hr>`,14)),p("p",null,[n[1]||(n[1]=t("via: ",-1)),o(e,{href:"http://www.unixmen.com/find-ip-conflicts-linux/"},{default:i(()=>[...n[0]||(n[0]=[t("http://www.unixmen.com/find-ip-conflicts-linux/",-1)])]),_:1})]),p("p",null,[n[4]||(n[4]=t("译者：",-1)),o(e,{href:"https://github.com/geekpi"},{default:i(()=>[...n[2]||(n[2]=[t("geekpi",-1)])]),_:1}),n[5]||(n[5]=t(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:i(()=>[...n[3]||(n[3]=[t("wxy",-1)])]),_:1})]),p("p",null,[n[8]||(n[8]=t("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...n[6]||(n[6]=[t("LCTT",-1)])]),_:1}),n[9]||(n[9]=t(" 原创翻译，",-1)),o(e,{href:"http://linux.cn/"},{default:i(()=>[...n[7]||(n[7]=[t("Linux中国",-1)])]),_:1}),n[10]||(n[10]=t(" 荣誉推出",-1))])])}const w=s(u,[["render",I]]);export{c as __pageData,w as default};
